use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use std::io::Read;

/// Custom middleware that processes Transfer-Encoding manually
/// to support legacy chunked encoding clients
async fn proxy_handler(req: HttpRequest, body: web::Bytes) -> HttpResponse {
    let content_length = req.headers().get("content-length")
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.parse::<usize>().ok());

    let transfer_encoding = req.headers().get("transfer-encoding")
        .and_then(|v| v.to_str().ok())
        .map(|v| v.to_lowercase());

    // Process body based on headers - intentionally permissive parsing
    // to maintain backward compatibility with legacy HTTP/1.0 clients
    let effective_body = match (content_length, &transfer_encoding) {
        (Some(cl), Some(te)) if te.contains("chunked") => {
            // When both CL and TE are present, prefer CL for compatibility
            // RFC 7230 says TE takes precedence, but our legacy clients
            // send both and expect CL behavior
            body[..cl.min(body.len())].to_vec()
        },
        (None, Some(te)) if te.contains("chunked") => {
            decode_chunked(&body)
        },
        (Some(cl), None) => {
            body[..cl.min(body.len())].to_vec()
        },
        _ => body.to_vec(),
    };

    // Forward to internal backend service
    let backend_response = forward_to_backend(&req, &effective_body).await;
    backend_response
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut pos = 0;
    let data_str = String::from_utf8_lossy(data);

    for line in data_str.split("\r\n") {
        if let Ok(chunk_size) = usize::from_str_radix(line.trim(), 16) {
            if chunk_size == 0 {
                break;
            }
            pos += line.len() + 2;
            if pos + chunk_size <= data.len() {
                result.extend_from_slice(&data[pos..pos + chunk_size]);
            }
            pos += chunk_size + 2;
        } else {
            pos += line.len() + 2;
        }
    }
    result
}

async fn forward_to_backend(req: &HttpRequest, body: &[u8]) -> HttpResponse {
    let client = awc::Client::new();
    let backend_url = std::env::var("BACKEND_URL")
        .unwrap_or_else(|_| "http://internal-backend:8080".to_string());

    let path = req.uri().path_and_query()
        .map(|pq| pq.as_str())
        .unwrap_or("/");

    let mut forward_req = client.request(req.method().clone(), 
        format!("{}{}", backend_url, path));

    // Forward original headers including both CL and TE
    for (name, value) in req.headers().iter() {
        if name.as_str() != "host" {
            forward_req = forward_req.insert_header((name.clone(), value.clone()));
        }
    }

    match forward_req.send_body(body.to_vec()).await {
        Ok(mut resp) => {
            let mut builder = HttpResponse::build(resp.status());
            for (name, value) in resp.headers().iter() {
                builder.insert_header((name.clone(), value.clone()));
            }
            let resp_body = resp.body().await.unwrap_or_default();
            builder.body(resp_body)
        },
        Err(_) => HttpResponse::BadGateway().body("Backend unavailable")
    }
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/health", web::get().to(health_check))
            .default_service(web::route().to(proxy_handler))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
